   198    {
   199      void init (hb_face_t *face)
   200      {
   201        table = hb_sanitize_context_t().reference_table<sbix> (face);
   202        num_glyphs = face->get_num_glyphs ();
   203      }
   204      void fini () { table.destroy (); }
