   216      hb_blob_t *reference_png (hb_font_t      *font,
   217                                hb_codepoint_t  glyph_id,
   218                                int            *x_offset,
   219                                int            *y_offset,
   220                                unsigned int   *available_ppem) const
   221      {
   222        return choose_strike (font).get_glyph_blob (glyph_id, table.get_blob (),
   223                                                    HB_TAG ('p','n','g',' '),
   224                                                    x_offset, y_offset,
   225                                                    num_glyphs, available_ppem);
   226      }
   227
   228      private:
   229
   230      const SBIXStrike &choose_strike (hb_font_t *font) const
   231      {
   232        unsigned count = table->strikes.len;
   233        if (unlikely (!count))
   234          return Null(SBIXStrike);
   235
   236        unsigned int requested_ppem = hb_max (font->x_ppem, font->y_ppem);
   237        if (!requested_ppem)
   238          requested_ppem = 1<<30; /* Choose largest strike. */
   239        /* TODO Add DPI sensitivity as well? */
   240        unsigned int best_i = 0;
   241        unsigned int best_ppem = table->get_strike (0).ppem;
   242
   243        for (unsigned int i = 1; i < count; i++)
   244        {
   245          unsigned int ppem = (table->get_strike (i)).ppem;
   246          if ((requested_ppem <= ppem && ppem < best_ppem) ||
   247              (requested_ppem > best_ppem && ppem > best_ppem))
   248          {
   249            best_i = i;
   250            best_ppem = ppem;
   251          }
   252        }
   253
   254        return table->get_strike (best_i);
   255      }
